"""Build a UTF-8 delivery report from the final homolog evidence."""
import hashlib,html,json
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'docs/revisao-visual-unificado/homolog/busca-20261120'
def read(name):return json.loads((O/name).read_text(encoding='utf-8'))
def esc(value):return html.escape(str(value),quote=True)
def link(name,label=None):return f'<a href="{esc(name)}">{esc(label or name)}</a>'
def table(headers,rows):return '<table><thead><tr>'+''.join(f'<th>{esc(v)}</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
b=read('browser-results.json');p=read('performance.json');a=read('final-check.json');d=read('deployment.json');after=read('production-after.json');syn=json.loads((R/'unificado/shell/busca-sinonimos.json').read_text(encoding='utf-8'))
assert b['all_ok'] and b['published_static'] and len(b['profiles'])==9 and len(b['captures'])==20
assert a['gate']=='7/7' and a['audit']['ok'] and read('approval.json')['approved']
assert a['hashes']['equal'] and read('release-manifest.json')['shell/busca.js']==hashlib.sha256((R/'unificado/shell/busca.js').read_bytes()).hexdigest()
tests=(O/'unit-tests.txt').read_text(encoding='utf-8');assert 'pass 59' in tests and 'fail 0' in tests
refs=json.loads((R/'tests/unificado/busca-referencia.json').read_text(encoding='utf-8'))
summary={'version':'1.4.29','scope':'homolog 18446 only','unit_tests_passed':59,'reference_queries':len(refs),'profiles_passed':9,'captures':20,'gate':'7/7','performance':p,'performance_limitation':'No physical tablet; exploratory 4x CPU emulation exceeded 50 ms. Final 2x measurement is explicitly emulated.','production_changed':False,'iam_changed':False,'service_restarts':0,'backup':d['backup'],'stopped_after_delivery':True}
(O/'result.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
roles=table(['Origem','Perfil','Conta existente','Telas autorizadas','Consultas','Conexões antes/depois','Resultado'],[(r['category'],r['role'],r['existing_user'],r['authorized_entries'],r['queries_checked'],f"{r['connections_before']} / {r['connections_after']}",'OK; nenhum item indevido') for r in b['profiles']])
synonyms=table(['Termo','Equivalente aprovado'],[(k,'; '.join(v)) for k,v in syn.items()])
perf=table(['Medição','P95 (ms)','Máximo (ms)'],[('Motor, catálogo completo',round(p['engine_p95_ms'],2),round(p['engine_max_ms'],2)),('Tratamento do input',round(p['ui_p95_ms'],2),round(p['ui_max_ms'],2)),('Input até próximo quadro',round(p['input_to_frame_p95_ms'],2),round(p['input_to_frame_max_ms'],2))])
shots=''.join(f'<tr><th>{w} px</th>'+''.join(f'<td>{link(f"{state}-{w}.png",label)}</td>' for state,label in [('recentes','Recentes'),('resultados','Resultados'),('correcao','Correção'),('sinonimo','Sinônimo'),('vazio','Sem resultado')])+'</tr>' for w in [1440,1024,820,390])
rollback=d.get('rollback_command') or d.get('rollback')
if not rollback:rollback='python3 /opt/concrefer-unificado/homolog-next/staging/busca-20261120/busca_rollback.py '+d['backup']
body=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Busca do Uni · homologação 1.4.29</title>
<style>body{{font:16px/1.55 system-ui,sans-serif;color:#0b1730;background:#f4f6f8;margin:0}}main{{max-width:1100px;margin:auto;background:white;padding:32px}}h1,h2{{line-height:1.2}}h2{{margin-top:32px}}table{{border-collapse:collapse;width:100%;font-size:14px;display:block;overflow:auto}}td,th{{text-align:left;padding:9px 12px;border:1px solid #dce2e9}}th{{background:#edf2f8}}a{{color:#15416f}}code,pre{{background:#f1f3f6;overflow-wrap:anywhere;white-space:pre-wrap}}.status{{background:#fff3cd;padding:12px 16px}}small{{color:#5b6779}}</style><main>
<h1>Busca de telas do Uni · 1.4.29</h1><p class="status">Disponível somente na <a href="https://concrefer.concretrack.com.br:18446/unificado/">homologação 18446</a>. Produção sem alteração. Entrega encerrada; sem push ou PR.</p>
<p>Motor único para a janela global, barra lateral, filtros de módulo no computador e celular e busca de telas da Logística. A publicação alterou 15 arquivos estáticos, com backup, sem reinício de serviço, nova API, escrita no banco ou concessão de acesso.</p>
<h2>Comportamento entregue</h2><ul><li>Índice limitado ao catálogo autorizado pela regra atual canUse e pelo snapshot de permissões centrais. GED usa o catálogo já existente. Itens de homologação são excluídos em simulação de produção. Armação permanece fora de escopo, não usada em produção.</li>
<li>Minúsculas, acentos, plurais simples e todas as palavras em qualquer ordem. Distância de edição 1 para 4–7 letras, 2 para 8 ou mais, transposição vizinha como 1. Números e siglas curtas exatos; sinônimos aprovados são equivalências explícitas.</li>
<li>Ordem: nome exato, prefixo, palavra do nome, descrição, grupo/módulo/unidade, sinônimo e correção. Empates usam destinos do acesso rápido e histórico de navegação existentes; depois, a ordem do catálogo.</li>
<li>Ctrl+K ou / fora dos campos de texto, botão Buscar, tela cheia no celular, grupos, unidade, descrição, destaques e selo de sinônimo. Setas, Enter, Esc, retorno do foco e foco preso; combobox/listbox/option e aria-activedescendant. Resultados em blocos de seis, mantendo a ordem completa; rolagem e setas carregam os demais. Cerca de seis resultados visíveis no computador.</li>
<li>Últimas cinco consultas em texto, somente neste aparelho, na chave unificado.busca.recentes, com try/catch e Limpar. Nenhuma consulta enviada ao servidor. O JSON estático de sinônimos é carregado na inicialização, sem chamada por tecla.</li>
<li>Campo do módulo preservado, com correção e sinônimos. Na Logística, o motor substitui apenas o filtro de telas; filtros de dados não fazem parte desta entrega.</li></ul>
<p>Descrições vêm de UnificadoPresentation.descriptions; quando ausentes, aparece o grupo existente. A implantação específica das páginas de módulo 1.4.28 continua separada e não foi executada nesta tarefa. A versão do login era 1.4.27; foi reservado o número 1.4.28 e usada a 1.4.29 para esta entrega.</p>
<h2>Sinônimos aprovados</h2><p>Decisão do usuário: “Aprovar os seis pares na homologação”. {link('approval.json','Registro da aprovação')} · {link('SINONIMOS_APROVACAO.html','Lista entregue para aprovação')}. Editáveis em shell/busca-sinonimos.json.</p>{synonyms}
<p>NF ↔ nota fiscal está cadastrado, mas o catálogo atual não possui tela correspondente. A consulta retorna vazia; não inventa uma tela e não consulta notas no ERP.</p>
<h2>Provas</h2><p>59 testes automatizados aprovados; 48 consultas de referência, sendo 43 com primeiro resultado fixo e cinco negativas. O teste falha se o primeiro resultado esperado mudar. Inclui acentos, erro de digitação, ordem de palavras, sigla, unidade, plural, transposição, ranking, isolamento de permissões e itens exclusivos da homologação. {link('unit-tests.txt','Saída dos testes')} · {link('../../../../tests/unificado/busca-referencia.json','Consultas de referência')}.</p>
<p>Matriz executada com uma tela por vez, usando sessões assinadas de contas existentes nos serviços de homologação. Sem criação de conta ou senha. Todas as 48 consultas por perfil retornaram somente itens autorizados. Inclui prova de carregamento adicional por setas e rolagem, atalhos, foco, histórico, navegação real para Etiquetas Setor 3 e filtro nativo de Logística.</p>{roles}
<p>{link('browser-results.json','Matriz em JSON')} · {link('logistica-correcao-1440.png','Logística: motoritas → Motoristas')} · {link('gate.txt','Gate 7/7')}.</p>
<table><thead><tr><th>Largura</th><th>Campo vazio</th><th>Resultados</th><th>Correção</th><th>Sinônimo</th><th>Sem resultado</th></tr></thead><tbody>{shots}</tbody></table>
<h2>Desempenho e limitação física</h2><p>Perfil final: Edge/Chromium no Windows, viewport 820 × 1180, CPU reduzida a {p['cpu_throttle']}×, catálogo de {p['catalogue_size']} itens incluindo os itens GED autorizados. Consultas executadas sem fetch; medição do input inclui trabalho síncrono e, separadamente, o próximo quadro. Valores abaixo de 50 ms neste perfil emulado.</p>{perf}
<p><strong>Não houve teste em tablet físico.</strong> O usuário autorizou registrar a emulação e essa limitação. Um ensaio exploratório com CPU 4× excedeu 50 ms e não é considerado aprovado. A aprovação em CPU 2× não comprova o limite em um tablet de referência. {link('performance.json','Medição final')} · {link('performance-frames.json','Amostras por consulta')} · {link('performance-stress-4x.json','Limitação do ensaio 4×')} · {link('tablet-decision.json','Decisão do usuário')}.</p>
<h2>Publicação, auditoria e reversão</h2><p>Gate 7/7. Auditoria por hash de {a['audit']['production_files']:,} arquivos de produção, configurações nginx/systemd e estado dos serviços, sem diferença inesperada. Atividades automáticas de timers oneshot ficam discriminadas no JSON. As cinco tabelas IAM observadas na homologação mantiveram os hashes. Nenhuma sessão encerrada, max_connections mantido, sem alteração de pool. Contagem final do cluster: {a['audit']['counts']['total']}; idle in transaction: {a['audit']['counts']['idle_in_transaction']}. Execução interrompe se o total ultrapassar 80.</p>
<p>Há uma diferença anterior entre fonte local e homologação: o rótulo “Indicador geral · 4 unidades”. O rótulo da homologação foi preservado na publicação. {link('source-parity-exceptions.json','Registro de paridade')}.</p>
<p>Backup completo desta publicação: <code>{esc(d['backup'])}</code>. A reversão restaura somente os 15 arquivos desta tarefa e remove os três ativos novos de busca. Comando no servidor:</p><pre>{esc(rollback)}</pre>
<p>Backups dos ajustes estáticos posteriores estão em {link('focus-patch.json')} e {link('feedback-patch.json')}; a reversão completa acima permanece válida.</p>
<p>{link('deployment.json','Publicação')} · {link('release-manifest.json','Manifesto final')} · {link('final-check.json','Verificação final')} · {link('production-before.json','Auditoria antes')} · {link('production-after.json','Auditoria depois')} · {link('source-changes.json','Escopo do commit')} · {link('commit.json','Recibo do commit local')}.</p>
<h2>Proposta futura</h2><p>Busca de dados deve ser um projeto separado, com fontes e permissões por tipo de registro, limites de consulta e revisão do fluxo. Não foi implementada busca de número de série, nota fiscal ou dados de traço.</p>
<p><strong>Produção exige “aprovado, publicar em produção”.</strong> Nenhuma pendência de conta ERP, permissão, API ou banco foi alterada por esta tarefa; continuam registradas nos relatórios anteriores.</p></main></html>'''
